var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('parse() must not extract a unit from a string that does not start with a number', function () {
    // The unit regexp is anchored (^...$), so a leading space makes the
    // match fail and parse() falls back to parseInt() over the whole
    // string, i.e. the value is treated as plain bytes. With an
    // unanchored regexp the trailing "1kb" is extracted and turned
    // into 1024 instead.
    assert.strictEqual(bytes.parse(' 1kb'), 1);
    assert.strictEqual(bytes.parse(' 1.5 kb'), 1);
  });
});

var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    assert.strictEqual(bytes.parse('10.5kb'), 10752, "parse('10.5kb') should be 10752");
    assert.strictEqual(bytes.parse('12.5mb'), 13107200, "parse('12.5mb') should be 13107200");
    assert.strictEqual(bytes.parse('100kb'), 102400, "parse('100kb') should be 102400");
  });
});

var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('keeps the default of 2 decimal places when options are passed without decimalPlaces', function () {
    assert.strictEqual(bytes(1024 * 1.25, {}), '1.25KB');
    assert.strictEqual(bytes.format(1536, { unitSeparator: ' ' }), '1.5 KB');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('throws the documented error for null and undefined', function () {
    assert.throws(function () { ms(null); }, /val is not a non-empty string or a valid number/);
    assert.throws(function () { ms(undefined); }, /val is not a non-empty string or a valid number/);
  });

  it('does not treat arrays or String objects as strings', function () {
    assert.throws(function () { ms(['2 days']); }, /val is not a non-empty string or a valid number/);
    assert.throws(function () { ms(new String('100')); }, /val is not a non-empty string or a valid number/);
  });

  it('still parses real strings and numbers', function () {
    assert.strictEqual(ms('2 days'), 172800000);
    assert.strictEqual(ms(1000), 1000);
    assert.strictEqual(ms(1000, { long: true }), '1 second');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('long format pluralizes when the value is exactly 1.5x a unit', function () {
    // Math.round displays 2 at exactly 1.5x a unit, and ms 2.1.3
    // (msAbs >= n * 1.5) therefore emits the plural form there.
    assert.strictEqual(ms(1500, { long: true }), '2 seconds');
    assert.strictEqual(ms(90000, { long: true }), '2 minutes');
    assert.strictEqual(ms(5400000, { long: true }), '2 hours');
    assert.strictEqual(ms(129600000, { long: true }), '2 days');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // 1 year = 365.25 days = 365.25 * 86400000 ms = 31557600000 ms
    assert.strictEqual(ms('1y'), 365.25 * 86400000);
    assert.strictEqual(ms('y'), 365.25 * 86400000);
    assert.strictEqual(ms('2yrs'), 2 * 365.25 * 86400000);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    assert.strictEqual(ms('1y'), 31557600000, 'ms("1y") should be 1 year in milliseconds');
    assert.strictEqual(ms('2yrs'), 2 * 31557600000, 'ms("2yrs") should be 2 years in milliseconds');
    assert.strictEqual(ms('-1y'), -31557600000, 'ms("-1y") should be -1 year in milliseconds');
  });
});
